INSERT INTO canonical_pod_scenarios SELECT * FROM json_populate_recordset(null::canonical_pod_scenarios, $tbr$[{"id":"learning-flagship:SC01-S01","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":1,"global_order":1,"speaker":"TOM","english_text":"Right. This is Tom and Aran talking bollocks, part five.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S02","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":2,"global_order":2,"speaker":"ARAN","english_text":"Of four.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:40:02.992471+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S03","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":3,"global_order":3,"speaker":"TOM","english_text":"Part five of four. Five years and one lockdown late.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S04","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":4,"global_order":4,"speaker":"ARAN","english_text":"Are you still going to put \"part five of eighteen million\"?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S05","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":5,"global_order":5,"speaker":"TOM","english_text":"Who knows. Let's just start anywhere.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S06","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":6,"global_order":6,"speaker":"ARAN","english_text":"We said that last time and it took four parts to reach the future of education. Start there. What's the actual question?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S07","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":7,"global_order":7,"speaker":"TOM","english_text":"Okay — three of them, stacked, take them in any order. What is education for, if we get to rebuild it from nothing? What would we build first? And what does one act of learning actually consist of — because I don't trust either of us on the first two until we've done that one.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S08","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":8,"global_order":8,"speaker":"ARAN","english_text":"That's not a stack, that's a funnel.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S09","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":9,"global_order":9,"speaker":"TOM","english_text":"It's a funnel. Take the wide end.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S10","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":10,"global_order":10,"speaker":"ARAN","english_text":"The wide end is the same as it was five years ago, and I'll say it fast because it's big. None of this happens on its own. Schooling is one moving part in a complex adaptive system, and what we're playing for at the end of it is eight billion minds now — connected, happy, up for it — that can go at complicated problems—","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 21:55:41.947009+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S11","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":11,"global_order":11,"speaker":"TOM","english_text":"Do some cool shit.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S12","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":12,"global_order":12,"speaker":"ARAN","english_text":"—very, very quickly. Yes. Through whatever bottleneck is coming. That end hasn't moved. What's changed is that I think we can now actually say what the small end of your funnel is. Five years ago we couldn't.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S13","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":13,"global_order":13,"speaker":"TOM","english_text":"Go on then. Smallest thing there is. One act of learning.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S14","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":14,"global_order":14,"speaker":"ARAN","english_text":"You first. I've heard the bird one.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S15","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":15,"global_order":15,"speaker":"TOM","english_text":"The bird one. You're looking at the sky. The first thing you notice is that some of the darkness is changing — something rather than nothing. Then that the moving thing isn't the background. Then that some of the moving things keep their size and some don't, some flap and some don't, the flappy ones come closer.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S16","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":16,"global_order":16,"speaker":"ARAN","english_text":"Keep going.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S17","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":17,"global_order":17,"speaker":"TOM","english_text":"Bird, then blackbird, then young blackbird, then that blackbird's not well — and at no point did anyone hand you a rule. You kept telling differences apart until the differences ran out.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S18","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":18,"global_order":18,"speaker":"ARAN","english_text":"They never run out.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S19","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":19,"global_order":19,"speaker":"TOM","english_text":"They never run out. That's the ornithologist. The ornithologist is not doing a different thing from the baby. The ornithologist is the baby who didn't stop.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S20","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":20,"global_order":20,"speaker":"ARAN","english_text":"And the word arrives when?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S21","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":21,"global_order":21,"speaker":"TOM","english_text":"Last. You say bird once the pattern has held long enough to be worth a label. The label is a receipt for a distinction that already stabilised. It's not the thing that does the stabilising.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S22","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":22,"global_order":22,"speaker":"ARAN","english_text":"Hold that one, because I want to fight you about it properly and I don't want to do it in the first ten minutes.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S23","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":23,"global_order":23,"speaker":"TOM","english_text":"Noted and parked. You'll lose.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S24","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":24,"global_order":24,"speaker":"ARAN","english_text":"We'll see. But as far as it goes — that's my edges story wearing your clothes, isn't it. I spent twenty years saying you don't know words, you know what's between them — which words plug into which, red bus, red house, never red went. You're saying the between is all there is, all the way down. Not just words. Birds. Everything.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S25","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":25,"global_order":25,"speaker":"TOM","english_text":"Everything. That's all learning is — increasingly fine distinctions on a signal that never stops being a signal. And that's why the eight billion minds don't get to float free of this. If we're wrong about what one act of learning is, we build the wrong everything, at scale, with conviction. Schools already did. They built for the labels.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 21:55:42.078797+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S26","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":26,"global_order":26,"speaker":"ARAN","english_text":"Warehouses for receipts.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S27","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":27,"global_order":27,"speaker":"TOM","english_text":"…I'm having that one.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S28","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":28,"global_order":28,"speaker":"ARAN","english_text":"You can have it. So that's the deal for the rest of this — we do the small end properly first, and then we're allowed the future.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S29","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":29,"global_order":29,"speaker":"TOM","english_text":"Agreed. And the recording still can't pick up your hands.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S30","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":30,"global_order":30,"speaker":"ARAN","english_text":"They still haven't found a way. I'm drawing the funnel. It's a lovely funnel.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S31","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":31,"global_order":31,"speaker":"TOM","english_text":"It's mostly a triangle.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC01-S32","pod_slug":"learning-flagship","scene_number":1,"scene_label":"Chapter 1","scene_title":"Part one of eighteen million","scene_subtitle":"the whole future of education stands on what one act of learning actually is","difficulty":null,"sentence_number":32,"global_order":32,"speaker":"ARAN","english_text":"Everything is, in the end.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S01","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":1,"global_order":33,"speaker":"ARAN","english_text":"Right, small end. Your bird stabilises because a bird cooperates. Same size every day, parts behaving, whoever happens to be looking. What's the sound wave for justice?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S02","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":2,"global_order":34,"speaker":"TOM","english_text":"Say more.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S03","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":3,"global_order":35,"speaker":"ARAN","english_text":"Your whole story is distinctions holding still, and physics is what holds a bird still. Nothing holds justice still. The six-year-old's justice and the law student's justice aren't the same thing, and neither of them flies past a window. If the account only works where physics does the holding, it's an account of perception, not of learning — and school can keep everything else.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S04","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":4,"global_order":36,"speaker":"TOM","english_text":"There's no such thing as an abstract topic.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S05","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":5,"global_order":37,"speaker":"ARAN","english_text":"Says the man who never marked essays on one.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S06","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":6,"global_order":38,"speaker":"TOM","english_text":"Really, there isn't. An abstract topic has to be explained in words, and words are themselves distinctions — precise sound waves, marks on a page standing for sound waves. So justice is a structure of distinctions like everything else. The difference was never the material. The difference is what does the holding.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S07","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":7,"global_order":39,"speaker":"ARAN","english_text":"Prove it the hard way. Define justice. Cold, no examples.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S08","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":8,"global_order":40,"speaker":"TOM","english_text":"Justice is fairness under— no, fairness is the same word in a hat. Justice is treating like cases alike, where \"like\" means— and there it goes. Listen to it. Now I need \"like\", and \"alike\", and \"case\", and each of those wants three more words, and the three want nine. I can feel the definition doing what every definition of an abstract does — running away from the floor, not towards it. There is no floor in that direction.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S09","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":9,"global_order":41,"speaker":"ARAN","english_text":"So where's the floor?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S10","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":10,"global_order":42,"speaker":"TOM","english_text":"Two children. One pizza. Cut it in half, give them half each. That's the floor. You might not share my agreement about a single one of the words, and you will still share that. The abstract concretises or it doesn't exist — you have to give examples, because an example is the only place the regress stops.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S11","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":11,"global_order":43,"speaker":"ARAN","english_text":"And a six-year-old owns that completely.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S12","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":12,"global_order":44,"speaker":"TOM","english_text":"Owns it before the word. And the law student thirty years up — proportionality, precedent, all of it — is the ornithologist again, on the same floor. Same operation, run further.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S13","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":13,"global_order":45,"speaker":"ARAN","english_text":"So the bird and the pizza are one machine—","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S14","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":14,"global_order":46,"speaker":"TOM","english_text":"—one machine, two stabilisers. The bird holds because physics holds it. Justice holds because we agree to keep holding it. That's what law actually is — patterns of stability, codified, so they don't have to be re-derived per punch-up.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S15","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":15,"global_order":47,"speaker":"ARAN","english_text":"And where the agreement hasn't converged, you get the grey. Which is most of the essays I never marked.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S16","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":16,"global_order":48,"speaker":"TOM","english_text":"You get green against blue. Eight billion people agree tremendously about the range of colours, and there is a permanent argument at the edges about where green becomes blue — and that's not a defect. Broad agreement with fuzzy borders is just what an agreement-stabilised distinction looks like. The grey is the signature, not the failure.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S17","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":17,"global_order":49,"speaker":"ARAN","english_text":"And at the border, Spanish and Italian?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S18","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":18,"global_order":50,"speaker":"TOM","english_text":"Same collapse, different purchase. Somebody in Seville and somebody in Bologna do the identical human thing to the identical orange — collapse a basket of wavelengths into one bin — and then buy different words for it. Which is the proof of the order: the binning is perception, the label is a purchase made afterwards.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S19","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":19,"global_order":51,"speaker":"ARAN","english_text":"Two layers, then. Things that hold because the world holds them, and things that hold because we do.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S20","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":20,"global_order":52,"speaker":"TOM","english_text":"Concepts and facts. A concept is a compression — derivable, universal, nobody's property. A fact is an agreement — arbitrary, social, joinable. That the angles of a triangle do what they do is a compression. That we call it a triangle is an agreement.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S21","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":21,"global_order":53,"speaker":"ARAN","english_text":"And school?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S22","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":22,"global_order":54,"speaker":"TOM","english_text":"School teaches the layers mixed, both ways at once. It drills agreements as if they were derivable — spell it, date it, name the parts — as if the name could be reasoned out by a sufficiently good child. And it explains compressions as if they were arbitrary — here is the rule for fractions, learn it — as if the structure were a decision someone took that you simply have to be told. Backwards, exactly, twice.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S23","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":23,"global_order":55,"speaker":"ARAN","english_text":"I want to sit on \"backwards\" a second, because that's most of a national curriculum indicted in one word and you said it like the price of fish.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S24","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":24,"global_order":56,"speaker":"TOM","english_text":"Which half don't you buy?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S25","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":25,"global_order":57,"speaker":"ARAN","english_text":"I'm checking, not refusing. For maths I buy it whole. For language — the words are agreements, drill them; the between is where the compressions live, let them emerge. Which is what I was doing for twenty years without the names for the halves. But I'm not conceding the between is all derivable. A Welsh mutation isn't derivable from anything. It's an agreement between words.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S26","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":26,"global_order":58,"speaker":"TOM","english_text":"Then it's a fact, and you drill it.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S27","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":27,"global_order":59,"speaker":"ARAN","english_text":"See, it always sounds tidy when you say it fast.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S28","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":28,"global_order":60,"speaker":"TOM","english_text":"It's tidier than it sounds slow, even. But keep the pizza on the table. I want it back when we get to communities.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S29","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":29,"global_order":61,"speaker":"ARAN","english_text":"Why would a pizza come back for communities?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S30","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":30,"global_order":62,"speaker":"TOM","english_text":"Because a community is the pizza agreement at scale. Later.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC02-S31","pod_slug":"learning-flagship","scene_number":2,"scene_label":"Chapter 2","scene_title":"The pizza","scene_subtitle":"two stabilisers: physics fixes the bird, agreement fixes justice","difficulty":null,"sentence_number":31,"global_order":63,"speaker":"ARAN","english_text":"Fine. Then I get the next one, because it's mine — what any of this costs.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S01","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":1,"global_order":64,"speaker":"ARAN","english_text":"What all of this costs, then — because here's what I keep coming back to. Your ornithologist: most people meet the same birds he does, and they get seagull, blackbird, robin, and they stop. Three bins, done, forty years. And the standard story is that they can't — no ear, no gift. I've spent my whole life listening to people tell me they can't learn languages, and it's the same sentence in different feathers.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S02","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":2,"global_order":65,"speaker":"TOM","english_text":"They're not incapable. They're not paying.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S03","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":3,"global_order":66,"speaker":"ARAN","english_text":"Go on.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S04","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":4,"global_order":67,"speaker":"TOM","english_text":"You've got a finite energy budget and you spend it according to what you find interesting. If you're not a designer, orange does you fine. If you are, you want the hex code — your orange has to survive being reproduced on every screen on earth. Neither of you has better eyes. You're funding different resolutions.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S05","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":5,"global_order":68,"speaker":"ARAN","english_text":"Funding. Not just buying.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S06","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":6,"global_order":69,"speaker":"TOM","english_text":"That's the part everyone misses. A distinction isn't a purchase, it's a subscription. You don't just learn the difference between a marsh tit and a willow tit — you maintain it, and the maintenance costs, forever. The non-birdwatcher isn't refusing to learn; he's declining a standing order. Which is also the honest economic name for spaced repetition — a maintenance schedule for the distinctions you decided to keep funding.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S07","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":7,"global_order":70,"speaker":"ARAN","english_text":"All right. Then break this, because I think it breaks it: whale song. Properly structured — more structured than birdsong on some axes. We can hear it. The recordings are everywhere, free. And nobody on earth hears it as music. Where's that in your budget? Nobody is declining to pay. There's nothing to pay for.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S08","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":8,"global_order":71,"speaker":"TOM","english_text":"…That's not a break. That's the basement. Say it again slowly, because your version is better than mine.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S09","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":9,"global_order":72,"speaker":"ARAN","english_text":"Whale song. We can hear it, and we can't hear it.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S10","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":10,"global_order":73,"speaker":"TOM","english_text":"We can't hear it as anything. The frequencies don't map onto any stable pattern we already hold — nothing lands on the piano keyboard in our heads, so a new distinction has nothing to stand next to. And that's worse than the budget, and more important: the ladder isn't just how you learn a thing. It's the limit of what you can currently notice. Below your bottom rung there's no such thing as hard. There's silence.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S11","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":11,"global_order":74,"speaker":"ARAN","english_text":"Inaudible, not hard.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S12","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":12,"global_order":75,"speaker":"TOM","english_text":"Inaudible, not hard. Which changes what a wrong question is. Ask a learner to tell two things apart across a gap finer than their finest current distinction, and you haven't asked a hard question — you've asked nothing at all, in a voice that sounds like asking.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S13","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":13,"global_order":76,"speaker":"ARAN","english_text":"I've watched that for twenty years and called it \"not ready\", which was kinder than it was accurate. Here — this proves nothing, but you'll have it anyway. The Chinese kids. Eight, ten years of English lessons, most of it dead on arrival, and everyone calls it failure.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S14","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":14,"global_order":77,"speaker":"TOM","english_text":"And then?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S15","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":15,"global_order":78,"speaker":"ARAN","english_text":"Then one word goes genuinely alive — one — and there's a spillover, like an electrical leak, and whole regions of the dead stuff light up. It was all in there, linked, waiting for one live thing it could stand next to. We've seen it over and over and over.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S16","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":16,"global_order":79,"speaker":"TOM","english_text":"Why that word and not another?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S17","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":17,"global_order":80,"speaker":"ARAN","english_text":"Don't know. Genuinely. Sometimes you guess, and you're wrong.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S18","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":18,"global_order":81,"speaker":"TOM","english_text":"Good. Then it's a thing you've seen and not a theory. Those are rarer and worth more.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S19","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":19,"global_order":82,"speaker":"ARAN","english_text":"And the thing learners say — \"it just felt right\", when a word comes out. I used to say that's all that's happening: there were no neural paths to any other word, so you went where the roads were. It's your picture from underneath. The paths are the budget, spent.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S20","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":20,"global_order":83,"speaker":"TOM","english_text":"So put the halves together, and I'll plant the flag we're going to trip over later. If stopping is a funding decision, and the silence below the bottom rung is a mapping problem — then nobody is a wall. Everyone is a rate. The slow learner is paying less per week, or being asked to hear whale song. Neither of those is a fact about what they could ever do.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S21","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":21,"global_order":84,"speaker":"ARAN","english_text":"Steady on. That's a much bigger sentence than the evidence you've put on the table.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S22","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":22,"global_order":85,"speaker":"TOM","english_text":"It is. I know it is. Leave it planted.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S23","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":23,"global_order":86,"speaker":"ARAN","english_text":"Planted. Flagged, mind — visibly flagged.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC03-S24","pod_slug":"learning-flagship","scene_number":3,"scene_label":"Chapter 3","scene_title":"Whale song","scene_subtitle":"distinctions cost maintenance, and the ladder is the limit of what you can notice","difficulty":null,"sentence_number":24,"global_order":87,"speaker":"TOM","english_text":"Visibly flagged. We'll come back with tools.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S01","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":1,"global_order":88,"speaker":"TOM","english_text":"Now.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S02","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":2,"global_order":89,"speaker":"ARAN","english_text":"Now?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S03","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":3,"global_order":90,"speaker":"TOM","english_text":"The parked one. You said you wanted to fight about the label arriving last, and you've just spent two chapters agreeing with me, so let's have it while you're weakened.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S04","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":4,"global_order":91,"speaker":"ARAN","english_text":"I've been agreeing with you about everything except the bit you care about. Scene first — agreed, always, no label before the felt thing. One distinction per blink — agreed; every item I've ever built is two options, one difference. The label is an agreement, not a derivation — agreed, you can have that too.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S05","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":5,"global_order":92,"speaker":"TOM","english_text":"So describe the item. The physics one. Say it exactly.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S06","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":6,"global_order":93,"speaker":"ARAN","english_text":"Flick a malteser off the table. Now flick a watermelon. Push a chair across the room, now push a car. Which one fought back? That's the scene, that's the felt floor, ten-year-old's body scale. And then — same session, next screen — \"the scientific name: màs. Unit: cilogramau.\" And the child has the word.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S07","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":7,"global_order":94,"speaker":"TOM","english_text":"Next screen.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S08","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":8,"global_order":95,"speaker":"ARAN","english_text":"Next screen. While their thumb still remembers the watermelon.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S09","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":9,"global_order":96,"speaker":"TOM","english_text":"And that's where we split.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S10","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":10,"global_order":97,"speaker":"ARAN","english_text":"Let me sell it properly first, because your own subscription argument is my best witness. A distinction with no name has no address. You can't bill maintenance on it. You can't ask the child about it on Thursday, they can't ask each other, the teacher can't reach it, it can't come up at tea. The name is the account number — and you want the direct debit set up while the scene is warm, because that's when it's cheapest.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S11","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":11,"global_order":98,"speaker":"TOM","english_text":"That's genuinely good. It's wrong, but it's the best wrong version I've heard, including mine.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S12","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":12,"global_order":99,"speaker":"ARAN","english_text":"Your turn, then. The rule.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S13","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":13,"global_order":100,"speaker":"TOM","english_text":"Four stages, in order. Grounded experience — your malteser, no quarrel. Understanding of the quantity — the child can use the thing, predict with it, before anyone says a word over it. Drill of the quantity — it comes out under pressure, in their own words, \"the heavy one fights back\".","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S14","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":14,"global_order":101,"speaker":"ARAN","english_text":"And then the word.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S15","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":15,"global_order":102,"speaker":"TOM","english_text":"LAST, the equivalence: by the way, the thing you already own — examiners call it mass. Drilled both directions, because the dropped mark is the child who owns the thing and goes blank at the word. The name is a fact. An agreement. It gets its own slot, joined to the built thing — never allowed to pretend it's the building.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S16","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":16,"global_order":103,"speaker":"ARAN","english_text":"You struck your own harder rule, though. Say that part.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S17","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":17,"global_order":104,"speaker":"TOM","english_text":"I did. I used to say some names never arrive at all. That's gone — struck it myself, because the exam speaks the agreement layer and full marks live there. So we already agree the name gets bought.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S18","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":18,"global_order":105,"speaker":"ARAN","english_text":"Which makes this a fight about the delivery date, and you're treating it like a fight about the soul.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S19","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":19,"global_order":106,"speaker":"TOM","english_text":"Because the delivery date IS the soul. Buy the name early and the name starts answering the questions. Ask about the watermelon and \"màs\" comes back, and you cannot tell whether that's the distinction speaking or the label doing an impression of it. The word is cheap to say and expensive to be fooled by. Every natural sequence we walked — the bird, the note, the orange — buys the label after stability, and I don't think nature is being sentimental.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S20","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":20,"global_order":107,"speaker":"ARAN","english_text":"The child in the classroom isn't in nature. They're in a school, where the word is the currency of the whole building, all year.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S21","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":21,"global_order":108,"speaker":"TOM","english_text":"Whale song, though. Having the word \"whale song\" doesn't let you hear it.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S22","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":22,"global_order":109,"speaker":"ARAN","english_text":"And nobody hands out words for things below the bottom rung — my scene puts the rung in first. That's what the malteser is FOR. And there's a thing you've never once weighed, because it isn't in any of your ledgers: the word is a trophy. A ten-year-old who says \"inertia\" at tea on Thursday is showing the family a thing they caught. That word does more for the standing order than any schedule of yours — pride pays subscriptions.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S23","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":23,"global_order":110,"speaker":"TOM","english_text":"So what you're saying is the name is scaffolding, and scaffolding comes down.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S24","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":24,"global_order":111,"speaker":"ARAN","english_text":"No. Wrong fight. Scaffolding comes down — the name stays up forever. I'm saying the name is part of the building. You're the one treating it as decoration bolted on for the inspectors.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S25","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":25,"global_order":112,"speaker":"TOM","english_text":"Taken. Then let's haggle the date, since you've made it a delivery problem. I'll come to: after the first successful transfer — the child uses the distinction on something the scene never showed them, then the word, same week.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S26","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":26,"global_order":113,"speaker":"ARAN","english_text":"Too late. End of the same session. The scene, the play, and the word goes on it while it's hot — one session, closed.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S27","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":27,"global_order":114,"speaker":"TOM","english_text":"End of session buys the impression-problem back. Anything said that soon gets credited to the word.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S28","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":28,"global_order":115,"speaker":"ARAN","english_text":"And your \"first transfer\" can be weeks, and for those weeks the thing has no handle in a building run entirely on handles.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S29","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":29,"global_order":116,"speaker":"TOM","english_text":"Then neither of us moves.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S30","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":30,"global_order":117,"speaker":"ARAN","english_text":"Neither of us moves.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S31","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":31,"global_order":118,"speaker":"TOM","english_text":"Good — because this is the one fork we own that isn't philosophy. Two arms, same scenes, same items, only the delivery date differs. Then watch two numbers: the recall rung on the name, and transfer to scenes neither arm has seen. If early names close questions, my arm's transfer beats yours and your recall beats mine early and evaporates. If the trophy pays subscriptions, your retention curve embarrasses me by Christmas.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S32","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":32,"global_order":119,"speaker":"ARAN","english_text":"Testable on telemetry rather than arguable.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S33","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":33,"global_order":120,"speaker":"TOM","english_text":"And we've been arguing anyway, because it's Tuesday and there's wine.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S34","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":34,"global_order":121,"speaker":"ARAN","english_text":"Telemetry, then.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S35","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":35,"global_order":122,"speaker":"TOM","english_text":"Telemetry. You'll lose.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC04-S36","pod_slug":"learning-flagship","scene_number":4,"scene_label":"Chapter 4","scene_title":"Màs","scene_subtitle":"whether a name is ever worth buying early","difficulty":null,"sentence_number":36,"global_order":123,"speaker":"ARAN","english_text":"One of us will.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S01","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":1,"global_order":124,"speaker":"ARAN","english_text":"Back up a level, because we've been talking about learners and I want one more go at the thing being learned. The rules of grammar. Where do they live, in the head?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S02","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":2,"global_order":125,"speaker":"TOM","english_text":"Ask it at the level of neurons.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S03","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":3,"global_order":126,"speaker":"ARAN","english_text":"That's exactly the discipline. How would it even work? A parallel system — word types, categories, a machine for putting them in order, another machine checking the first machine, somewhere to store all that, and a way for a three-year-old to build it before she can tie her shoes. You say it out loud and you can hear it getting complicated, fast. And that's the tell. It's complicated, so that can't be a thing.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S04","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":4,"global_order":127,"speaker":"TOM","english_text":"The razor. Still the sharpest thing you own.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S05","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":5,"global_order":128,"speaker":"ARAN","english_text":"It's done twenty years of work and it's never once needed sharpening. The rules exist — in the book, as a perfectly good description of what comes out of people's mouths, four hundred years of scholastic hotchpotch, Latin forced onto English, you can't split an infinitive because in Latin it's one word. Barking mad. But a description of the outputs and the machinery producing them are different things, and nobody has a model of the machinery that survives the neuron question.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S06","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":6,"global_order":129,"speaker":"TOM","english_text":"Then what's in there?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S07","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":7,"global_order":130,"speaker":"ARAN","english_text":"Here's how far it goes, and I still get vertigo relaying it. Alison Wray — formulaic language, about as highly regarded as the field gets — has been saying in conversation, I don't think she's published it: there's no such thing as a word. There aren't any. And every time I've heard her say it I've thought — yep, my brain is already hurting, and I can't keep up, and she might be right.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S08","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":8,"global_order":131,"speaker":"TOM","english_text":"Woo.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S09","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":9,"global_order":132,"speaker":"ARAN","english_text":"Fully woo. But try to define \"word\" so that \"to boldly go\" comes out as three of them and \"listless\" comes out as one, and watch every definition die. Unit of contained meaning? Then \"to boldly go\" is one word.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S10","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":10,"global_order":133,"speaker":"TOM","english_text":"So if words are shaky and rules are a description — what's actually in there?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S11","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":11,"global_order":134,"speaker":"ARAN","english_text":"Two ingredients. Information about items — call them words, even if they don't exist — and information about the edges between them. Which item can follow which. Red bus, red house, one that's red — never red went. Not a rule anybody stored; there are paths from this cluster to those, and none to that one. And two ingredients is enough — items plus edges gives you emergent behaviour. You don't need the second machine. There's no grammar module. There's a landscape.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S12","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":12,"global_order":135,"speaker":"TOM","english_text":"And when a learner says \"it just felt right\" —","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S13","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":13,"global_order":136,"speaker":"ARAN","english_text":"—there were no roads going anywhere else. We did that one.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S14","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":14,"global_order":137,"speaker":"TOM","english_text":"So now the consequence, and check it against twenty years of learners. If the thing is items and edges, the thing is a graph. It's a bloody graph. You can go in any direction you like.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S15","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":15,"global_order":138,"speaker":"ARAN","english_text":"And a syllabus?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S16","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":16,"global_order":139,"speaker":"TOM","english_text":"One walk through it — somebody's walk, usually a dead somebody's — sold to the child as if the walk were the territory. Chapter three comes after chapter two because it did in 1975. The subject doesn't have an order. It has neighbourhoods.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S17","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":17,"global_order":140,"speaker":"ARAN","english_text":"So what you're saying is nobody has ever taught anybody grammar.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S18","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":18,"global_order":141,"speaker":"TOM","english_text":"Roughly that, said dangerously.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S19","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":19,"global_order":142,"speaker":"ARAN","english_text":"Then let me say it more dangerously, because I've watched the bill get paid. Everyone who ended up with grammar built it themselves, out of exposure to edges — and then the school charged them for the description, and the ones who couldn't pay twice were told they were bad at languages. That's the sharpened version. It's not that teaching grammar fails. It's that it never happened. There's no such event.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S20","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":20,"global_order":143,"speaker":"TOM","english_text":"Taken, sharpened, and slightly frightening. So here's my objective function, and you tell me if it survives contact. Minimum admitted, maximum minted. The minimum number of things we have to introduce and state — and then the maximum of things the learner can mint as a result. Admit items, admit the felt floors. Everything else is minted, by the learner, in the landscape. The whole curriculum question becomes: what's the smallest set of admissions with the biggest minting yield?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S21","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":21,"global_order":144,"speaker":"ARAN","english_text":"Say the word again.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S22","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":22,"global_order":145,"speaker":"TOM","english_text":"Minted.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S23","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":23,"global_order":146,"speaker":"ARAN","english_text":"Minted. Because that's what the play is. When I finally understood why the playful bit mattered — it's the mint. Give people permission to combine, even when the combination doesn't communicate anything yet, and every combination that clicks is a coin they struck themselves. Your drama game —","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S24","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":24,"global_order":147,"speaker":"TOM","english_text":"Holy Dickhead Batman. Everyone stands in a circle and recombines it. Holy BatHead ManDick. Holy DickMan Bathead. Pointless, joyful, and every single recombination is teaching your mouth that the units are units.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S25","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":25,"global_order":148,"speaker":"ARAN","english_text":"And nobody ever forgot a coin they struck themselves. Which brings me to the evening class, since you've handed me the loaded gun. Twice a week, two hours. New vocabulary items, a bit of conjugation, if you're lucky some role-play. Five to ten years to a real conversation, and everyone around you on the same timetable, so it feels normal.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S26","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":26,"global_order":149,"speaker":"TOM","english_text":"Item-rich, edge-poor.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S27","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":27,"global_order":150,"speaker":"ARAN","english_text":"And no model of memory at all, on top. What you learned in week one is gone by week two, and week two is new stuff anyway, and the syllabus never comes back except at random.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S28","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":28,"global_order":151,"speaker":"TOM","english_text":"The path isn't just the wrong shape. It's unmaintained.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S29","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":29,"global_order":152,"speaker":"ARAN","english_text":"And then the bit that actually breaks my heart, and I'm going to say it the way I always say it. You'll see kids who really care, really trying, and you look at their workbooks and they're full of fucking highlighting.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S30","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":30,"global_order":153,"speaker":"TOM","english_text":"And the results are in.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S31","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":31,"global_order":154,"speaker":"ARAN","english_text":"It does nothing. Worse than nothing; it costs the time it takes. Nobody told them how to form a memory, because their teachers aren't memory specialists either and were never told themselves. They're busting their guts on a method proven not to work, and we're letting them down. Just shatteringly.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S32","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":32,"global_order":155,"speaker":"TOM","english_text":"Systemic. Not one villain anywhere in it.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S33","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":33,"global_order":156,"speaker":"ARAN","english_text":"Not one. Everyone in the building is doing what they saw done. That's what a bad graph walk looks like from the inside — it looks like tradition.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S34","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":34,"global_order":157,"speaker":"TOM","english_text":"So the mint isn't a nicety. It's the difference between a subject you own and a route you were bussed along.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC05-S35","pod_slug":"learning-flagship","scene_number":5,"scene_label":"Chapter 5","scene_title":"A bloody graph","scene_subtitle":"the rules are a description, and the thing is edges","difficulty":null,"sentence_number":35,"global_order":158,"speaker":"ARAN","english_text":"And they remember the bus. That's the cruel bit. They remember the bus and think it was the country.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S01","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":1,"global_order":159,"speaker":"ARAN","english_text":"My turn to bring the loaded gun. Pimsleur — first person to build spaced repetition into language courses, and clever about it. He said repetitions collapse in value, so revisit the word just before you forget it. Lovely rule, everyone still quotes it, and I think he made one interesting, non-obvious mistake.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S02","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":2,"global_order":160,"speaker":"TOM","english_text":"Which was?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S03","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":3,"global_order":161,"speaker":"ARAN","english_text":"Bjork. Desirable difficulty: the early repetitions fail precisely because they're too easy. Say pysgod ten times in a row and you're not forming a memory at all. The act of making effort is a significant contributor to the act of forming the memory. And if effort is implicated in memory formation — then Pimsleur is inverted. The right time to revisit isn't just before you forget.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S04","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":4,"global_order":162,"speaker":"TOM","english_text":"Just after.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S05","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":5,"global_order":163,"speaker":"ARAN","english_text":"Just after. Or long after. So I started stretching the gap, on myself, to find the edge. A week — still too easy. A month. Kept going.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S06","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":6,"global_order":164,"speaker":"TOM","english_text":"Sixteen months?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S07","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":7,"global_order":165,"speaker":"ARAN","english_text":"Sixteen months, and here's the protocol, because the shape of it matters. Teach me a sentence of Manx on day one — I want to watch football at the weekend. Leave it sixteen months, no contact. Prompt me: guaranteed, absolutely guaranteed, I cannot produce it. That was sixteen months ago, up yours.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S08","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":8,"global_order":166,"speaker":"TOM","english_text":"And then?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S09","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":9,"global_order":167,"speaker":"ARAN","english_text":"You tell me the answer — once. Come back the day after and ask again, and I have got it nailed. The struggle followed by the restimulation. Five repetitions total, spread over a year and a half, and it holds like a rock.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S10","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":10,"global_order":168,"speaker":"TOM","english_text":"Sample size?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S11","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":11,"global_order":169,"speaker":"ARAN","english_text":"One. Hello, me. Plus a steady trickle of other people's letters saying the same shape, which is a pile of anecdotes and not a study, and I fly that flag myself before you reach for it.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S12","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":12,"global_order":170,"speaker":"TOM","english_text":"Then let me do the thing properly, because I did it to you five years ago and I'd do it again. How do we know that? Effort makes the memory — I feel it's true, it seems to work. But where are we, actually? Is it mapped, peer-reviewed, \"proven scientific fact\"? Or is it one careful man in California with a good idea, and us with a feeling?","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S13","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":13,"global_order":171,"speaker":"ARAN","english_text":"Closer to the man in California, still. Bjork's careful and the work is good, and proven is not the word. What I've got on top is me, testing myself for years, and other people's letters. That's not proof; that's a story with a flag on it. So — we think. We don't know. We think.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S14","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":14,"global_order":172,"speaker":"TOM","english_text":"We think. Held. And the practice works anyway, which is the strangest part of this whole field — truth in the practice with no consistency about the why.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S15","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":15,"global_order":173,"speaker":"ARAN","english_text":"Ebbinghaus all the way down. Now cash it, because the inversion isn't a curiosity — it splits your world in half. If longer gaps mean fewer total repetitions, then there are two different things you could be minimising, and they are not the same thing.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S16","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":16,"global_order":174,"speaker":"TOM","english_text":"Say the axes.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S17","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":17,"global_order":175,"speaker":"ARAN","english_text":"X: minimum elapsed time from start to ability. Y: minimum total effort to get there. And they pull apart, genuinely. Down at my end of Y: an hour a year for thirty years and you'll speak the language — the model breaker, and I think it would broadly work. A day a year, and three or four years in you're having conversations that make you proud. Nobody sells that product, because nobody believes it until it happens to them.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S18","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":18,"global_order":176,"speaker":"TOM","english_text":"It happened to me. Two days of Mandarin, a year apart — and by the end of the second day I had more felt competence than a hard month has ever given me. Thinking in Chinese, feeling the structures move. Two days. The system is extraordinary and what it is, is intelligent laziness — a month's mountain for two days of walking, because the year in between did the carrying.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S19","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":19,"global_order":177,"speaker":"ARAN","english_text":"And then say the next thing you said, five years ago, because it's the other half and you always forget you said it.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S20","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":20,"global_order":178,"speaker":"TOM","english_text":"…That if I actually needed Chinese by the end of October, the method was no use to me, because the course didn't exist yet and the gaps do the work and gaps take calendar.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S21","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":21,"global_order":179,"speaker":"ARAN","english_text":"Efficiency is lovely. But so is speed.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S22","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":22,"global_order":180,"speaker":"TOM","english_text":"Speed means you can start using it now. And using it is where all the actual value lives — the conversations, the connections, the compounding. An hour a year optimises the integral and forfeits a decade of use.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S23","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":23,"global_order":181,"speaker":"ARAN","english_text":"So: two axes, two honest products, and every learner sits somewhere on the trade — the heritage learner who wants five sentences for her great-grandfather is at one corner, your October deadline is at the other, and the bootcamp-year-bootcamp is a bet placed on both at once. All fine. Now — your theory. Name it for the recording.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S24","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":24,"global_order":182,"speaker":"TOM","english_text":"Least-time learning.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S25","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":25,"global_order":183,"speaker":"ARAN","english_text":"Mm. Go on, the whole shape.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S26","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":26,"global_order":184,"speaker":"TOM","english_text":"Fermat. Light takes the path of least time through a medium; the subject is the medium, distinction density is the refractive index, the learner is the ray, and the curriculum is the geodesic. The quantity being minimised is learner effort-time — the felt cost at the blink, the hesitations, the debt when a false bridge gets repaid. Everything the theory prices, it prices in that currency.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S27","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":27,"global_order":185,"speaker":"ARAN","english_text":"Effort-time. Which is my Y axis. You've built a least-EFFORT theory, and you've hung least-TIME over the door. Run your own shop rule on your own signage: a name is bought when payoff beats cost. What this name buys you is a conflation — intensives sell speed, polyglots hear \"least time\" and think October. Elapsed and integrated are different quantities that happen to share a unit, and sharing a unit is exactly how conflations get into a building.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S28","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":28,"global_order":186,"speaker":"TOM","english_text":"I priced the alternatives. Least-action is righter and worse — \"action\" charges a parse toll and drags half of physics in with it. Time is owned by everyone. The name is honest at the level of the unit, and the unit is where the theory does its accounting.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S29","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":29,"global_order":187,"speaker":"ARAN","english_text":"The unit is where the theory does its accounting, and the AXIS is where the customer does theirs.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S30","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":30,"global_order":188,"speaker":"TOM","english_text":"So what you're saying is I should rename it least-effort learning.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S31","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":31,"global_order":189,"speaker":"ARAN","english_text":"No. I'm saying you haven't decided which product you're selling, and the name is hiding the indecision from you. The hour-a-year learner and the bootcamp learner are buying different promises, and one brand is currently making both of them. That's not a signage problem.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S32","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":32,"global_order":190,"speaker":"TOM","english_text":"Then here's what I'll give you, and it's all I'll give you. The name stays. And the caveat travels with it — said out loud, every time, forever: least-time is an effort theory, and any compressed intensive is optimising the other axis.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S33","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":33,"global_order":191,"speaker":"ARAN","english_text":"Then you'll be saying that sentence for the rest of your life.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S34","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":34,"global_order":192,"speaker":"TOM","english_text":"Good. Some subscriptions are worth the standing order.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S35","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":35,"global_order":193,"speaker":"ARAN","english_text":"And which axis is the promise? Because \"both\" is not an answer, it's a brochure.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC06-S36","pod_slug":"learning-flagship","scene_number":6,"scene_label":"Chapter 6","scene_title":"An hour a year","scene_subtitle":"elapsed time and total effort are different axes","difficulty":null,"sentence_number":36,"global_order":194,"speaker":"TOM","english_text":"I know. Not tonight.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S01","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":1,"global_order":195,"speaker":"ARAN","english_text":"Right. The flag from an hour ago. Dig it up — nobody is a wall, everyone is a rate. Full strength this time.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S02","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":2,"global_order":196,"speaker":"TOM","english_text":"Full strength. Every ten-year-old has both the experience and the vocabulary necessary to learn anything at all — anything — provided the grounding is real and the subsequent steps are small enough. It's a claim about the graph, not about children: the territory is connected, all the way from things a ten-year-old has felt to every summit there is. There is no summit with no path. Ability is a rate coefficient. It is never a wall.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S03","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":3,"global_order":197,"speaker":"ARAN","english_text":"Anything at all.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S04","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":4,"global_order":198,"speaker":"TOM","english_text":"Anything at all. And notice what it does to the school equation, because this is the whole inversion: school holds time constant and lets learning vary — everyone gets the year, and some children get the physics. The premise holds learning constant and lets time vary — everyone gets the physics, and the year takes as long as it takes. One knob, moved from one variable to the other, and the entire moral architecture of \"bad at maths\" falls over.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S05","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":5,"global_order":199,"speaker":"ARAN","english_text":"It's beautiful. You know it's beautiful. Now hold still.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S06","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":6,"global_order":200,"speaker":"TOM","english_text":"Here it comes.","author_notes":null,"created_at":"2026-08-30 19:35:30.838985+00","updated_at":"2026-08-30 19:35:30.838985+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S07","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":7,"global_order":201,"speaker":"ARAN","english_text":"How do we know that? Your question — I'm returning it in its original packaging. Effort and memory got the full customs inspection an hour ago: where are we, is it mapped, is it proven, or is it a man with a good idea and a feeling. So: the connected graph, the rate that's never a wall. Where are we?","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S08","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":8,"global_order":202,"speaker":"TOM","english_text":"Asserted.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S09","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":9,"global_order":203,"speaker":"ARAN","english_text":"Asserted.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S10","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":10,"global_order":204,"speaker":"TOM","english_text":"Fifteen years of watching learners do things they'd been told they couldn't, which is a mountain of the same anecdote — and you taught me this evening what a pile of anecdotes is. It's a story with a flag on it. So: asserted. We think. We don't know.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S11","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":11,"global_order":205,"speaker":"ARAN","english_text":"Then I want to press on something worse than \"we don't know\", because I've been turning it over since you said \"provided\". Twice. Provided the grounding is real, provided the steps are small enough. Now watch what those two do in the wild. A child fails to learn a thing. What do we say?","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S12","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":12,"global_order":206,"speaker":"TOM","english_text":"The grounding wasn't real. Or a step was too big.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S13","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":13,"global_order":207,"speaker":"ARAN","english_text":"Fix, retry. Fails again? Same diagnosis, always available, forever. There is no possible failure that counts AGAINST the premise, because the provisos absorb every one of them. That's not a foundation, Tom. That's a fortress. Nothing gets in.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S14","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":14,"global_order":208,"speaker":"TOM","english_text":"And you're about to say what would have to be true for it to be testable—","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S15","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":15,"global_order":209,"speaker":"ARAN","english_text":"—I am—","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S16","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":16,"global_order":210,"speaker":"TOM","english_text":"—and it's exactly where I was going, so I'll say it for both of us and the credit is yours: you'd have to commit the repair budget in advance. Before the child starts. This much re-grounding, this many step-splittings, priced and written down — and if we spend the budget and the learning still hasn't landed, THEN the failure counts. No pre-committed budget, no test, ever. The provisos eat the evidence forever.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S17","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":17,"global_order":211,"speaker":"ARAN","english_text":"So you know. You've known the whole time. And here's what I actually want to ask, and it isn't rhetorical. There was a test designed, wasn't there — the ordering claim checks out as refutable on the telemetry you already collect, no new machinery. And the premise needs the budget. And you looked at all of it and called it—","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S18","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":18,"global_order":212,"speaker":"TOM","english_text":"A vanity project. I said we're going to do what we think is best and do that as fast as possible. And I'll defend it, so hear the whole shape before you swing. The premise isn't functioning as a hypothesis in this system. It's functioning as a founding commitment — the thing you select before the evidence, that then generates everything.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S19","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":19,"global_order":213,"speaker":"ARAN","english_text":"Go on.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S20","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":20,"global_order":214,"speaker":"TOM","english_text":"The way \"all men are created equal\" wasn't a finding. Nobody ran a trial. It's a selection, frozen, and its justification is what it builds, not what it predicts. My system is honest exactly as long as it names its axioms as axioms.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S21","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":21,"global_order":215,"speaker":"ARAN","english_text":"Then NAME it. That's the whole charge. That sentence doesn't dress like an axiom. It wears a lab coat. \"Every ten-year-old CAN\" sounds like a discovery about children, and parents will hear one, and when a child's year goes wrong the fortress will do what fortresses do. If it's a creed, print CREED on it. You — the man who makes examiners' agreements wear their own name — don't get to let your deepest sentence pass as the other kind of thing.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S22","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":22,"global_order":216,"speaker":"TOM","english_text":"…That landed. I want one thing on the record before I answer properly, though, because there's a third door — it's not creed-or-trial, there's a cheaper instrument that's been sitting in the telemetry the whole time, and it doesn't need the budget to start paying. It's the way corrections—","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S23","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":23,"global_order":217,"speaker":"ARAN","english_text":"Dog. That's the dog.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S24","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":24,"global_order":218,"speaker":"TOM","english_text":"Of course it's the dog. Five years. Same dog.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S25","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":25,"global_order":219,"speaker":"ARAN","english_text":"She has a sense of structure. Bank it — say the word so we can find it again.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S26","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":26,"global_order":220,"speaker":"TOM","english_text":"Repair budget. And \"the way corrections\" — mine, unfinished, I want it back exactly there.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S27","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":27,"global_order":221,"speaker":"ARAN","english_text":"Repair budget, corrections, banked. Next lockdown?","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC07-S28","pod_slug":"learning-flagship","scene_number":7,"scene_label":"Chapter 7","scene_title":"Any ten-year-old","scene_subtitle":"the universality premise, and whether it can be tested at all","difficulty":null,"sentence_number":28,"global_order":222,"speaker":"TOM","english_text":"Don't even joke. Go and see to your dog.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S01","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":1,"global_order":223,"speaker":"ARAN","english_text":"Where were we?","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S02","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":2,"global_order":224,"speaker":"TOM","english_text":"Repair budget. Corrections.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S03","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":3,"global_order":225,"speaker":"ARAN","english_text":"\"The way corrections\" — you got six words in. Finish the sentence. Same six words.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S04","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":4,"global_order":226,"speaker":"TOM","english_text":"There's a cheaper instrument that's been sitting in the telemetry the whole time, and it doesn't need the budget to start paying. It's the way corrections behave.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S05","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":5,"global_order":227,"speaker":"ARAN","english_text":"Behave.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S06","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":6,"global_order":228,"speaker":"TOM","english_text":"A correction is the signal of another rung — that's the axiom's own small print, and it's the testable bit. If the premise is right, then when a learner gets something wrong, the wrongness isn't noise and it isn't a verdict — it's an arrow pointing at a rung that isn't there yet. Supply the rung, and that correction should never come back. Not \"less often\". Not come back.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S07","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":7,"global_order":229,"speaker":"ARAN","english_text":"And if it does come back?","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S08","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":8,"global_order":230,"speaker":"TOM","english_text":"Then watch WHERE it comes back, because the two worlds sign their names differently. If ability is a wall, recurring corrections cluster by child — the same children stumble everywhere, whatever you do about rungs, and the premise is dead and I want to know.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S09","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":9,"global_order":231,"speaker":"ARAN","english_text":"And if you're right?","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S10","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":10,"global_order":232,"speaker":"TOM","english_text":"They cluster by node — everyone stumbles at the same missing rung, bright kids and slow kids alike, and the child washes out of the signature entirely. Same telemetry we already collect. No new machinery. No budget needed to start reading it.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S11","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":11,"global_order":233,"speaker":"ARAN","english_text":"Clusters by child, or clusters by node. That's a real instrument. That's actually a beautiful instrument.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S12","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":12,"global_order":234,"speaker":"TOM","english_text":"So the fortress gets a window, and the siege can stand down.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S13","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":13,"global_order":235,"speaker":"ARAN","english_text":"…You think I was besieging you.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S14","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":14,"global_order":236,"speaker":"TOM","english_text":"Weren't you?","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S15","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":15,"global_order":237,"speaker":"ARAN","english_text":"No — and I want this one corrected on the record. I wasn't attacking the castle; I want the premise to be true more than you do — I've bet more years on it than you have. My whole charge was about the COAT. I did exactly this to you about Bjork, remember — we think, not we know — and did we stop shipping? We shipped for five more years. Honest labels and full speed are not opposites.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S16","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":16,"global_order":238,"speaker":"TOM","english_text":"Taken, and the record so shows. I heard \"prove it or drop it\" and you were saying \"name it and keep going\". Those are different sentences and I defended against the wrong one.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S17","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":17,"global_order":239,"speaker":"ARAN","english_text":"Good. Then in the spirit of honest labels: the window you just installed — corrections clustering — that tests the RUNG story. It still doesn't test \"anything at all\". The summit half of your premise stays creed even with the window open.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S18","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":18,"global_order":240,"speaker":"TOM","english_text":"It does. The signature can kill the premise — clusters by child and I'm finished — but it can't crown it. For the crown you need the budget, pre-committed, and a summit nobody believes a ten-year-old can reach, and years.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S19","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":19,"global_order":241,"speaker":"ARAN","english_text":"So write the number down. Tonight, while it costs nothing. The budget — this much re-grounding, this many splittings, priced. You said yourself: no pre-committed budget, no test, ever.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S20","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":20,"global_order":242,"speaker":"TOM","english_text":"…Not tonight. And here's the true sentence underneath that, which you can have at full price: if the signature comes back clusters-by-child, I'll write the number the same day, because I'll need to know what I'm wrong about. Until then I'm going to keep building as if the premise holds, because that's the bet the whole thing IS.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S21","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":21,"global_order":243,"speaker":"ARAN","english_text":"That's a promise with a proviso. From the man I fined for provisos yesterday.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S22","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":22,"global_order":244,"speaker":"TOM","english_text":"It's the best true sentence I have.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S23","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":23,"global_order":245,"speaker":"ARAN","english_text":"Then I'm writing down that you didn't write it down.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S24","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":24,"global_order":246,"speaker":"TOM","english_text":"Noted.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S25","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":25,"global_order":247,"speaker":"ARAN","english_text":"We think. We don't know. We think.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC08-S26","pod_slug":"learning-flagship","scene_number":8,"scene_label":"Chapter 8","scene_title":"Where were we","scene_subtitle":"asserted, not tested, shipping anyway","difficulty":null,"sentence_number":26,"global_order":248,"speaker":"TOM","english_text":"And we build anyway. That's either the whole method or the whole disease, and the dog stopped us finding out which.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S01","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":1,"global_order":249,"speaker":"TOM","english_text":"Now the one I've been saving, because you built something and I don't think either of us has ever said out loud what it is. Your exam trees. Walk me down one.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S02","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":2,"global_order":250,"speaker":"ARAN","english_text":"The arholiad trees. Forty a subject, two levels deep, every one written by hand.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S03","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":3,"global_order":251,"speaker":"TOM","english_text":"The heater.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S04","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":4,"global_order":252,"speaker":"ARAN","english_text":"A twenty-ohm heater on two hundred and forty volts — what's the current? Child gets it wrong. Don't mark it — descend: you've got two hundred and forty volts and twenty ohms; how do you find the current? Wrong again — descend again: if you divide a voltage by a resistance, what do you get? That one they can nearly always answer. Then you climb back up, and the top question that was a wall three minutes ago is a doorstep.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S05","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":5,"global_order":253,"speaker":"TOM","english_text":"And my machine, on the same wrong answer, does something that sounds identical and is a different move in a different structure. Which is the fork, so let's get both on the table properly before we start swinging.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S06","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":6,"global_order":254,"speaker":"ARAN","english_text":"Yours drops a rung.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S07","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":7,"global_order":255,"speaker":"TOM","english_text":"Mine drops a rung on the SAME question. The ladder under every node runs seven deep — recall at the top, then construct, precision, method, type and units, magnitude, and category at the bottom: is it even a fish.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S08","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":8,"global_order":256,"speaker":"ARAN","english_text":"Walk the heater down it.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S09","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":9,"global_order":257,"speaker":"TOM","english_text":"Miss at precision and the next question is the same heater with wider distinctions — did you get the magnitude right, are you in amps at all — down, if it keeps going wrong, to \"is current even the kind of thing we're looking for\". Same node. Wider apart. Your whale rule running the show: if they missed it, maybe the question was inaudible — make it audible, find the rung they CAN hear.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S10","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":10,"global_order":258,"speaker":"ARAN","english_text":"Same trigger, two descents.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S11","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":11,"global_order":259,"speaker":"TOM","english_text":"Two structures. I walk down the LADDER — the distinction axis, inside one question. You walk down the ASSEMBLY — out of the question entirely, toward the prerequisite it's built from. And here's what should worry both of us: an hour ago I said a correction is the signal of another rung, and you let it straight through.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S12","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":12,"global_order":260,"speaker":"ARAN","english_text":"Rung of what?","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S13","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":13,"global_order":261,"speaker":"TOM","english_text":"Exactly that. Rung of what. My ladder has rungs. Your tree has rungs. The sentence doesn't know which structure it lives in, and neither of us noticed for five years.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S14","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":14,"global_order":262,"speaker":"ARAN","english_text":"Then let me name what your machine actually is, because I've been inside it now. It's clean. The cleanest architecture in the building — the frontier decides what you're ready for, the mastery gate swears you own the prerequisites, so by the time a question reaches you, a prerequisite failure is supposed to be impossible, and the ladder only ever has to handle slips.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S15","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":15,"global_order":263,"speaker":"TOM","english_text":"That's the design, yes.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S16","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":16,"global_order":264,"speaker":"ARAN","english_text":"And that's precisely where it's blind. The gate's oath is only as good as the graph, and the graph is always slightly wrong about what a real child owns on a real Tuesday. Your architecture handles the world where your bookkeeping is right. Mine handles the world.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S17","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":17,"global_order":265,"speaker":"TOM","english_text":"And let me name what you actually built. You hand-authored, forty times a subject, by ear, the exact walk a prerequisite graph would generate — every one of your trees is a stack of assembly edges, written by a man who swears the graph doesn't need to exist. You built the second axis. My engine even HAS the machinery for it, and it's wired to selection time, never to a miss. You wired it to the miss. By hand. Forty times.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S18","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":18,"global_order":266,"speaker":"ARAN","english_text":"So we've each built half of one machine, and the fight is over which half answers the phone.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S19","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":19,"global_order":267,"speaker":"TOM","english_text":"The FIRST wrong answer. That's the whole fork. One event, one default. Taxonomy first, though, because we agree on more than we're about to pretend: some misses are slips—","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S20","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":20,"global_order":268,"speaker":"ARAN","english_text":"—precision, fumble, misread, the ladder's meat, no argument—","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S21","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":21,"global_order":269,"speaker":"TOM","english_text":"—some are inaudible questions, distinction too fine, still ladder—","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S22","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":22,"global_order":270,"speaker":"ARAN","english_text":"—and some are debts. The prerequisite was never owned, the gate swore falsely, and no amount of widening THIS question touches it, because the hole is two nodes upstream.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S23","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":23,"global_order":271,"speaker":"TOM","english_text":"Both structures needed. Obviously. Nobody's arguing axes exist.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S24","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":24,"global_order":272,"speaker":"ARAN","english_text":"The default, then. Your machine hears the miss first — what does it do?","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S25","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":25,"global_order":273,"speaker":"TOM","english_text":"Ladder. Always ladder first. It's the cheapest probe there is: one wider question, same node, and a slip declares itself instantly — most misses ARE slips, and sending every fumble on a tour of the prerequisites turns a typo into a remedial event. If the fish rung fails, THEN jump structures, because now it can't be a slip. The ladder is the diagnostic; the assembly is the treatment.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S26","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":26,"global_order":274,"speaker":"ARAN","english_text":"And I say by the time your fish rung fails you've marched a child through three failures in a row to confirm what the first one was screaming. Listen to the tree again — the child gets the FLOOR. Every descent of mine ends, within two questions, on something they can answer, and then they climb back up on their own legs and take the summit that beat them three minutes ago.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S27","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":27,"global_order":275,"speaker":"TOM","english_text":"And mine?","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S28","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":28,"global_order":276,"speaker":"ARAN","english_text":"Yours bottoms out at \"is it even a fish\" — the question whose honest translation is \"do you know anything at all?\" — and you'd serve it to a child who was one missing rung from glory. That's not a diagnostic sequence. That's an experience, being had by a person.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S29","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":29,"global_order":277,"speaker":"TOM","english_text":"The dignity argument.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S30","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":30,"global_order":278,"speaker":"ARAN","english_text":"The dignity FINDING. I tested it. Forty trees, two subjects, real children, real exams — it's the best-tested thing either of us owns and I didn't theorise it, I watched it work and wrote down more of it.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S31","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":31,"global_order":279,"speaker":"TOM","english_text":"So what you're saying is a wrong answer is a referral.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S32","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":32,"global_order":280,"speaker":"ARAN","english_text":"No.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S33","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":33,"global_order":281,"speaker":"TOM","english_text":"Then say the bedrock, because we're there. Mine: a wrong answer is INFORMATION ABOUT THE QUESTION. The child is the one fixed point I trust; the miss tells me my question was mis-pitched or my graph is lying, and the machine's first duty is to interrogate ITSELF — which the ladder does, cheaply, before it dares conclude anything about the learner.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S34","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":34,"global_order":282,"speaker":"ARAN","english_text":"And mine: a wrong answer is AN EXPERIENCE OF A CHILD. Whatever it tells your bookkeeping, it is also, right now, a person being wrong, and what happens in the next thirty seconds decides whether they come back tomorrow. The machine's first duty is to the person having the worst moment of the session. Everything else can be logged and settled later.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S35","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":35,"global_order":283,"speaker":"TOM","english_text":"Both of those are true.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S36","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":36,"global_order":284,"speaker":"ARAN","english_text":"Both of those are true, and they give different orders to the same machine, and one of them has to answer the phone.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S37","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":37,"global_order":285,"speaker":"TOM","english_text":"Then it stands.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S38","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":38,"global_order":286,"speaker":"ARAN","english_text":"It stands. And notice we didn't do the thing we did with the names — there's no telemetry sentence coming, because we'd both predict the same mixed result. Some misses slips, some misses debts, film at eleven. The instrument doesn't split us. The default is a decision about what a wrong answer IS, and that's a selection, not a measurement.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S39","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":39,"global_order":287,"speaker":"TOM","english_text":"The scarce thing was always the selector.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC09-S40","pod_slug":"learning-flagship","scene_number":9,"scene_label":"Chapter 9","scene_title":"The wrong answer","scene_subtitle":"descend the ladder or descend the assembly","difficulty":null,"sentence_number":40,"global_order":288,"speaker":"ARAN","english_text":"Even here. Especially here.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S01","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":1,"global_order":289,"speaker":"TOM","english_text":"Communities, then. And I owe you a pizza from two nights ago.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S02","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":2,"global_order":290,"speaker":"ARAN","english_text":"You do. But I get to earn it with a story first, and the story proves nothing—","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S03","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":3,"global_order":291,"speaker":"TOM","english_text":"—lost your foot in that river, I know. Accept it anyway.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S04","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":4,"global_order":292,"speaker":"ARAN","english_text":"Always. So: Jeremy Vine. He'd got himself in hot water — a Twitter storm about Welsh, mostly a misunderstanding — and I went down to London expecting the crews to be bracing for the angry Welshman. Instead, every single person I was introduced to — editors, producers, camera people — had prepped a word or two of Welsh. Each of them. Badly, with effort, in the wrong order. And I stood there receiving it, and something in me went: oh no. We were wrong.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S05","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":5,"global_order":293,"speaker":"TOM","english_text":"Wrong about what, exactly — say the old position.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S06","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":6,"global_order":294,"speaker":"ARAN","english_text":"The old position was the language-activist reflex: three words of Welsh is classic tokenism, an empty gesture, to hell with you. We used to laugh about it. And we were utterly wrong. Every one of those people, with their two words, formed a connection that would not otherwise have existed — instantly, on a plate, and it required them to have learned nothing else.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S07","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":7,"global_order":295,"speaker":"TOM","english_text":"And then you taught him the sentence.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S08","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":8,"global_order":296,"speaker":"ARAN","english_text":"Seventy per cent of a sentence. I want to learn to speak Welsh today, because — and the producers are making cut-throat signs at me because I will not leave the studio until he's finished it, and he never finished it. Seventy per cent.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S09","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":9,"global_order":297,"speaker":"TOM","english_text":"And then?","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S10","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":10,"global_order":298,"speaker":"ARAN","english_text":"The part that still stops me. That was a year and a half ago, and he hasn't had a single guest on since then slagging off the language. Not one booking. Because now, when someone rings in with \"they're all bastards, let me tell my story\", his filter goes — really? Can you back that up? Two extra questions. That's all a worldview is, operationally. Two extra questions at the door.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S11","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":11,"global_order":299,"speaker":"TOM","english_text":"So look at what you're describing, priced. Seventy per cent of one sentence — call it an hour of effort, all in. And it bought eighteen months of changed editorial behaviour on a platform with millions of listeners, and it's still paying. That's not communication. That's value created once and never destroyed — it just keeps moving. It's the best specimen I own of the thing I keep trying to tell economists.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S12","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":12,"global_order":300,"speaker":"ARAN","english_text":"And you can aim it. That's the part that scales: twenty or thirty opinion formers in London, one sentence each, and the whole media conversation about Wales changes. Or the general form — where there's conflict and distrust, teach group A one sentence in the language of group B, and group B one sentence in the language of group A, and you've probably got a significant dampening effect immediately. Real emotional connections. One sentence each way.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S13","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":13,"global_order":301,"speaker":"TOM","english_text":"Which no fluency programme would ever have bought, at any budget.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S14","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":14,"global_order":302,"speaker":"ARAN","english_text":"Right — and before I cash your pizza, a detour, because it explains why Vine had me on at all. Detour. Flagged.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S15","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":15,"global_order":303,"speaker":"TOM","english_text":"Clock's running.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S16","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":16,"global_order":304,"speaker":"ARAN","english_text":"The pub myth. He'd had a guest with the hoary old chestnut: I walked into a pub in Wales and they all stopped speaking English and switched to Welsh about me. The myth is immortal because it's a confirmation-bias machine. Bilinguals in casual settings code-switch constantly. A monoglot walks in, hears the word \"fridge\" float past, and his brain files the whole conversation as English. Then he listens properly, hears it's Welsh, and concludes: they've changed languages because I'm here.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S17","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":17,"global_order":305,"speaker":"TOM","english_text":"And how did they know?","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S18","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":18,"global_order":306,"speaker":"ARAN","english_text":"THAT'S the question he never asks! What was the magical instrument that detected him before the door opened? Was he wearing his I-don't-speak-Welsh t-shirt? There aren't any of those. And your relationship with a person tends to be a linguistic relationship — parents and kids who both speak fluent Welsh will still speak English to each other forever if that's how they started. Nobody switches AT you. The whole myth needs Welsh to be a conspiracy rather than a language.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S19","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":19,"global_order":307,"speaker":"TOM","english_text":"Detour returned?","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S20","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":20,"global_order":308,"speaker":"ARAN","english_text":"Returned. Forty seconds over budget, worth every one. The point of it: one live myth, in one influential head, cost the language more than a thousand learners could repair — and one sentence, spoken with effort, retired it. That's the exchange rate we're dealing in.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S21","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":21,"global_order":309,"speaker":"TOM","english_text":"So now the groups, because everything so far is one person's sentence. And I know this one's a wound, so I'll ask it straight: come and run one. Five days, a group, Cambridge, my filter on the door.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S22","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":22,"global_order":310,"speaker":"ARAN","english_text":"No.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S23","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":23,"global_order":311,"speaker":"TOM","english_text":"I'll fill the room with people you'd pick yourself.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S24","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":24,"global_order":312,"speaker":"ARAN","english_text":"Still no — and here's the reason. One on one, I can guarantee the experience: whatever the working memory or the nerves, I can calibrate, and they leave taller. With a group, the learning isn't the risk — the FORMATION is. Four people, five days, a bed and breakfast in rural Wales, and one of them just having a couple of bad-tempered days — not even a bad person — and every drop of it lands on the learning of the other three.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S25","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":25,"global_order":313,"speaker":"TOM","english_text":"The pairing story. Tell it, because it's the whole mechanism in one couple.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S26","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":26,"global_order":314,"speaker":"ARAN","english_text":"One group. One genuinely negative person in it. And the most positive man in the room paired with her — deliberately, kindly, to encourage her, I watched him decide to do it. By the end of the session he was as negative as she was. It went the wrong way down the wire.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S27","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":27,"global_order":315,"speaker":"TOM","english_text":"That's literally how cancer works.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S28","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":28,"global_order":316,"speaker":"ARAN","english_text":"That is literally how cancer works. And it's why I stopped — not because groups don't work. The opposite, and this is what makes it hurt: solve the formation problem and a group is orders of magnitude more powerful than anything I can do alone.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S29","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":29,"global_order":317,"speaker":"TOM","english_text":"Say the afterwards part.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S30","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":30,"global_order":318,"speaker":"ARAN","english_text":"The group achieves communicative confidence TOGETHER, and then forever, when they bump into each other at the pub — a little bit of this language, out it comes, no appointment needed. The practice-partner problem, the great gear-change failure of every solo learner, just doesn't exist for them.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S31","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":31,"global_order":319,"speaker":"TOM","english_text":"Because they didn't learn a language. They became a place where it's spoken.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S32","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":32,"global_order":320,"speaker":"ARAN","english_text":"And your road trip thing is the right container for it — I've come round on that completely. Flexible, temporary, bonds you can't buy, and crashes. Actual crashes, and the crashes are load-bearing: nobody on that trip is getting any practice at being alive with other humans anywhere else in their week. The algorithm has us siloed with people who already agree with us. A learning road trip is the antidote sold as a holiday.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S33","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":33,"global_order":321,"speaker":"TOM","english_text":"Then here's the lift, and it's the pizza. Justice holds because people keep agreeing to hold it — two children, one pizza, the agreement is the floor. Now scale it. A community IS people who keep agreeing to hold things — that's all it is, a standing pattern of held agreements. Which means a community can LEARN: it can come to hold a distinction none of its members needed to hold alone.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S34","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":34,"global_order":322,"speaker":"ARAN","english_text":"Vine's newsroom.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S35","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":35,"global_order":323,"speaker":"TOM","english_text":"Owns a filter now. The town that learns group B's sentence owns a rung. And if a community is a learner, everything we said all evening applies one level up — it has a budget, it has whale song it can't hear yet, it has a bottom rung you have to find, and there's a least-time path THROUGH a community the same as through a child. Same functional. Two scales. Learner-seconds and community-hours.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S36","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":36,"global_order":324,"speaker":"ARAN","english_text":"A community is a learner. Say it like that, flat, because it's better flat.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S37","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":37,"global_order":325,"speaker":"TOM","english_text":"A community is a learner.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S38","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":38,"global_order":326,"speaker":"ARAN","english_text":"And nobody in development or education talks like that. They talk about delivering programmes TO communities — pallets of curriculum off the back of a lorry. Nobody asks what the community can currently hear.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S39","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":39,"global_order":327,"speaker":"TOM","english_text":"So pitch it. You're in front of a town council — Gwynedd, Cambridge, anywhere — thirty seconds, and you can't say \"complex adaptive system\" or they'll have you removed.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S40","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":40,"global_order":328,"speaker":"ARAN","english_text":"Councillors. I'm not asking you for money and I'm not teaching your residents Spanish. I'll show you what your town can do that it doesn't know it can do — and I'll prove it in an hour, with one sentence, at the point of maximum grumpiness. Give me your most sceptical councillor, right now. If nothing happens in this room that surprises you, I'll leave. I'm giving you my personal guarantee, and I've never once had to pay out on it.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S41","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":41,"global_order":329,"speaker":"TOM","english_text":"And the guarantee is the road trip trick again — they're not trusting the method, they're trusting you.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC10-S42","pod_slug":"learning-flagship","scene_number":10,"scene_label":"Chapter 10","scene_title":"The pub","scene_subtitle":"a community is a learner","difficulty":null,"sentence_number":42,"global_order":330,"speaker":"ARAN","english_text":"For the first hour. That's all trust is for. After that the thing works in the room, and the room does the rest — the room always does the rest.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S01","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":1,"global_order":331,"speaker":"TOM","english_text":"So. Small end done — two sessions of it. The deal was that we'd then be allowed the future. Say the order, because five years ago you corrected me on it and the dog ate the rest.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S02","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":2,"global_order":332,"speaker":"ARAN","english_text":"Education layer first. Not the currency — the currency is where we're going, and I still believe we'll get there, but it's not the first move. The first move is a full play for the education layer: every language through every language, then every subject. A full-stack remote school — you subscribe to the school, wherever you are, because obviously you do; it's the school. Reinvested so deep and so wide that attacking it is nobody's good idea.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S03","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":3,"global_order":333,"speaker":"TOM","english_text":"And above it?","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S04","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":4,"global_order":334,"speaker":"ARAN","english_text":"The layer above builds itself, nearly. Someone learns physics with you and gets good — they now WANT terrific physics programmes, and they want their groups, and it's all inside the same subscription. There's a natural layer up there that becomes your entertainment layer, and you're producing it anyway.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S05","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":5,"global_order":335,"speaker":"TOM","english_text":"Which is where the Netflix collision happens.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S06","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":6,"global_order":336,"speaker":"ARAN","english_text":"Where the Netflix collision fails to happen, if we're right. For the learner it's not competition — transcripts rather than subtitles, and that distinction is load-bearing: read the transcript first, then listen with your ears and nothing else. Condensations, synopses, the stepladder into real media. Netflix isn't taking any of that on. And a person who learned English inside your world has to actively decide to leave it for Netflix — first mover, held by value.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S07","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":7,"global_order":337,"speaker":"TOM","english_text":"And the content itself tilts good, which sounds naive and isn't.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S08","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":8,"global_order":338,"speaker":"ARAN","english_text":"It's a structural fact, not a hope. It is genuinely hard to write a script encouraging people to hate other people — it makes you look shitty, and you do that stuff behind closed doors, and when it does get out everyone hates it. Storytelling is such a human activity that it curves towards being kind to humans. So the layer pumps positivity by default — you'd have to work against the grain to make it do otherwise.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S09","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":9,"global_order":339,"speaker":"TOM","english_text":"Now the part where somebody listening says: lovely, and why are two men in a farmhouse planning a Netflix. Say the engine honestly, because we said it five years ago and I've never wanted to change a word.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S10","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":10,"global_order":340,"speaker":"ARAN","english_text":"We're a language company. Loads of those. It's a tenner a month and it's extremely good value for a tenner a month — no lock-in tricks, no worker exploitation, no consumer exploitation. A pretty morally acceptable formula, and — because it scales — capable of extracting very large amounts of capital anyway. And the extraction is the point. The extraction device is where we get the capacity to start freeing up people's time.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S11","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":11,"global_order":341,"speaker":"TOM","english_text":"Which is the actual scarce resource. Everyone thinks the bottleneck is money or ideas. Cambridge taught me otherwise — fifteen people, university think-tank, genuinely brilliant, solving energy for the world, and the ten-year project went cold in two because every one of those fifteen was time-poor. Caught in the structure they were trying to fix. Meanwhile the same project with five thousand time-rich people in Gwynedd — which do you back?","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S12","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":12,"global_order":342,"speaker":"ARAN","english_text":"And we've already started, at toy scale: ten people work for us, nobody does more than about twenty hours, everyone gets a full-time salary. Freed time. You fund an ignition event, the ignition event frees more time, the freed time funds the next ignition event — and somewhere in there it stops needing you and looks like a cascade.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S13","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":13,"global_order":343,"speaker":"TOM","english_text":"The currency mechanics are on the old tape — demurrage, the refund taper, the council tax move — and the dog ate the ending, so tonight I'll spend one sentence on it and no more: solve for the thing that's consuming people's resources, and that thing is needing to work for currency. The rest is mechanism, and mechanism keeps.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S14","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":14,"global_order":344,"speaker":"ARAN","english_text":"Agreed. One sentence and banked, and this time I'm not giving you the word to find it by.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S15","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":15,"global_order":345,"speaker":"TOM","english_text":"And the reason none of this is fantasy economics: scarcity is provably wrong by every metric that matters. We're not losing atoms of water. The sun's daily flux is absurd. The shortages are all in the plumbing, and plumbing is a solvable class of problem — the fight is only ever with whoever owns the current pipes.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S16","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":16,"global_order":346,"speaker":"ARAN","english_text":"Which is why they'll reach for the legislature, and why the politics matters less than it looks like it should — because politics, as we knew it—","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S17","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":17,"global_order":347,"speaker":"TOM","english_text":"—is already dead. It just doesn't know it yet.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S18","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":18,"global_order":348,"speaker":"ARAN","english_text":"We both said that five years ago, more or less in unison, and I've seen nothing since to revive the patient. Does anyone still believe the elected structures have the CAPACITY for decisions at this complexity — never mind the intentions? The world got too complex for the instrument. You don't fight an instrument like that. You build the alternative and let it shrivel.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S19","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":19,"global_order":349,"speaker":"TOM","english_text":"And the money to build alternatives wants to be spent. Feeney — the man who gave away eight billion, in his own lifetime, and kept the flat in New York and finished poor. Deliberately. Because giving it away in real time, watching it work, turned out to be the good bit. There are more of him coming. Show a working ignition event and the co-funding walks in — it doesn't have to be all your own money and it never was.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S20","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":20,"global_order":350,"speaker":"ARAN","english_text":"And schools, in this picture — I keep coming back to your line about them.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S21","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":21,"global_order":351,"speaker":"TOM","english_text":"Maybe it's schools that don't have a future, exactly — universities extend to all ages, schools merge into them and become outreach, reaching down into communities. Multi-generational learning communities with the content made super-cheap and super-good underneath them. Which — notice — is your road trip and my pizza and the whole of last chapter wearing institutional clothes.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S22","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":22,"global_order":352,"speaker":"ARAN","english_text":"It is. The town that learns together. We keep arriving at the same building from different streets.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S23","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":23,"global_order":353,"speaker":"TOM","english_text":"So let me walk back down the funnel, because we made a deal in the first ten minutes and I want to check we kept it. We were only allowed all this — the layers, the currency, the eight billion minds doing cool shit very, very quickly — if we did the smallest thing first.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 21:55:42.211366+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S24","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":24,"global_order":354,"speaker":"ARAN","english_text":"And did we?","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S25","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":25,"global_order":355,"speaker":"TOM","english_text":"The claim of the whole evening is that the tower actually rests there: one distinction, stabilising, on a signal that never stops being a signal. A community can hold one. A newsroom held one for eighteen months off seventy per cent of a sentence. Get the smallest thing right and every layer above it is engineering. Get it wrong and the tower is a warehouse for receipts — at planetary scale, with a subscription model.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S26","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":26,"global_order":356,"speaker":"ARAN","english_text":"Warehouses for receipts. Still having it.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S27","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":27,"global_order":357,"speaker":"TOM","english_text":"It was always yours. And one more piece of housekeeping before the dog wakes up: the ledger. Read out what's still open, because I think the open items are the evening's actual product.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S28","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":28,"global_order":358,"speaker":"ARAN","english_text":"The ledger, then. One: the name — when it's bought. Telemetry pending; we both still expect to win, which is the healthy kind of pending. Two: your theory's promise — effort or elapsed, which axis; the caveat travels but the question didn't close. Three: the repair budget — unwritten, and I have it minuted that it's unwritten. Four: the wrong answer — ladder or assembly, information or experience.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S29","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":29,"global_order":359,"speaker":"TOM","english_text":"And four stands. Not pending — standing. There's no instrument coming for it, because it's a selection, and we're the selectors, and we selected differently.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S30","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":30,"global_order":360,"speaker":"ARAN","english_text":"Four open, none fudged. That's a good evening. That might be the definition of a good evening.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S31","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":31,"global_order":361,"speaker":"TOM","english_text":"It's the healthiest ledger we've ever had. And notice what buys it — there's nothing between us. No record, no rank, no reason either of us has to be right. Two people with nothing to hold over each other can afford to leave four things standing. Most rooms can't. Most classrooms can't, which might be half of what's wrong with them.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S32","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":32,"global_order":362,"speaker":"ARAN","english_text":"The dog's asleep.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S33","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":33,"global_order":363,"speaker":"TOM","english_text":"First time in five years she's let us finish.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S34","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":34,"global_order":364,"speaker":"ARAN","english_text":"We haven't finished. We've got four open items and a currency you banked with no retrieval word.","author_notes":null,"created_at":"2026-08-30 19:35:30.989182+00","updated_at":"2026-08-30 19:35:30.989182+00","variant_key":null,"target_text":null,"target_lang":null,"attach_sentence_number":null},{"id":"learning-flagship:SC11-S35","pod_slug":"learning-flagship","scene_number":11,"scene_label":"Chapter 11","scene_title":"The layer above","scene_subtitle":"education layer first, and what still is not agreed","difficulty":null,"sentence_number":35,"global_order":365,"speaker":"TOM","english_text":"Part six, then.","author_notes":null,"create